<?php use Moves\Services\Helpdesk as H; use Moves\Support\CmsView as V;
$cats = ['' => 'Todas as categorias']; foreach (H::categories() as $c) { $cats[$c['id']] = $c['name']; }
$agents = ['' => 'Todos os responsáveis', 'none' => 'Sem responsável']; foreach (H::agents() as $a) { $agents[$a['user_id']] = trim($a['first_name'] . ' ' . $a['last_name']); }
$controls = $showFilters ? V::searchForm('Protocolo, assunto ou e-mail', ['status' => [$filters['status'], ['' => 'Todas as situações'] + V::TICKET_STATUS, 'Situação'], 'priority' => [$filters['priority'], ['' => 'Todas as prioridades'] + V::PRIORITIES, 'Prioridade'], 'category' => [$filters['category'], $cats, 'Categoria'], 'assignee' => [$filters['assignee'], $agents, 'Responsável'], 'overdue' => [$filters['overdue'], ['' => 'Qualquer prazo', '1' => 'Vencidos'], 'Prazo']]) : ''; ?>
<section class="cms-list"><?= V::listHead('Chamados', $result['total'] . ' registro(s)', $controls) ?>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhum chamado encontrado.') ?><?php else: ?><form method="post" action="/acao/ticket-bulk-status" data-confirm="Alterar a situação dos chamados selecionados?"><?= V::csrf() ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Chamados"><table><thead><tr><th><span class="cms-sr">Selecionar</span></th><th>Protocolo</th><th>Atualizado</th><th>Solicitante</th><th>Assunto</th><th>Status</th><th>Responsável</th><th>Prioridade</th><th>Prazo</th></tr></thead><tbody><?php foreach ($result['rows'] as $t): $sla = H::slaLabel($t); ?><tr><td><input type="checkbox" name="ids[]" value="<?= (int) $t['id'] ?>" aria-label="Selecionar <?= V::e($t['protocol']) ?>"></td><td><a href="/chamados/<?= (int) $t['id'] ?>"><code class="cms-chip"><?= V::e($t['protocol']) ?></code></a></td><td><?= V::date($t['last_activity_at']) ?></td><td><?= V::e($t['requester_email']) ?></td><td><a href="/chamados/<?= (int) $t['id'] ?>"><?= V::e($t['subject']) ?></a><br><small><?= V::e($t['category_name']) ?></small></td><td><?= V::badge($t['status'], V::TICKET_STATUS[$t['status']] ?? $t['status']) ?></td><td><?= V::e($t['assignee_name'] ?? 'Não atribuído') ?></td><td><?= V::badge($t['priority'], V::PRIORITIES[$t['priority']] ?? $t['priority']) ?></td><td><?= $sla === 'Vencido' ? V::badge('overdue', $sla) : V::e($sla) ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if (\Moves\Services\CmsAuth::can($admin, 'tickets.reply')): ?><div class="cms-bulkbar"><select name="status" aria-label="Com os selecionados"><?php foreach (V::TICKET_STATUS as $key => $label): ?><option value="<?= V::e($key) ?>"><?= V::e($label) ?></option><?php endforeach; ?></select><button class="cms-btn">Aplicar aos selecionados</button></div><?php endif; ?></form><?= V::pager($result) ?><?php endif; ?></section>
